// Not a test: the tool that mints HQ's mesh keypair.
//
// It lives here because `flutter test` is the only way to run Dart with this
// project's dependencies resolved, and because the pair MUST be generated by the
// same code that seals against it — a keypair produced by a different tool with
// a different point encoding is a channel that silently never decrypts.
//
// Run it deliberately:
//
//   MESH_KEYGEN=1 flutter test test/mesh_keygen_test.dart
//
// Without that variable it does nothing. An ordinary `flutter test` run must not
// print key material into a CI log, even material nobody will use: a build log
// is readable by more people than a key ever should be, and a habit of seeing
// keys in logs is how a real one ends up there.
//
// WHAT TO DO WITH THE OUTPUT
//
//   * The PRIVATE half goes into the HQ server's environment as
//     MESH_HQ_PRIVATE_KEY, and nowhere else. Not in this repository, not in a
//     ticket, not in a chat message. It opens every mesh alert ever sent,
//     including ones sent before it was compromised, because the ephemeral
//     halves are destroyed by the handsets that made them.
//   * The PUBLIC half ships to handsets through `app_config`, so it can be
//     rotated without a release, and is carried in each envelope's `keyId` so
//     HQ knows which key a frame was sealed to during a rotation.
//   * Generate it on a machine you trust, not in CI.
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:rainbow_app/core/mesh/mesh_sealer.dart';

void main() {
  test('mint an HQ mesh keypair', () {
    if (Platform.environment['MESH_KEYGEN'] != '1') {
      // Deliberately a pass, not a skip: this file is in the normal test run and
      // must neither fail it nor print anything into it.
      expect(true, isTrue);
      return;
    }

    final pair = meshGenerateHqKeypair();
    final private = _hex(_bytes(pair.privateKey, 32));
    final public = _hex(pair.publicKey);

    // A sanity check before anybody deploys it: the pair this printed must
    // actually open what it seals. A pair that cannot is worse than no pair,
    // because the failure appears only when a real alert arrives.
    final sealed = meshSeal(
      plaintext: Uint8List.fromList('round trip'.codeUnits),
      hqPublicKey: pair.publicKey,
    );
    final opened = meshOpen(sealed: sealed, hqPrivateKey: pair.privateKey);
    expect(opened, isNotNull, reason: 'the minted pair does not round-trip');

    stdout.writeln('''

  ── HQ mesh keypair ───────────────────────────────────────────────────────

  PRIVATE (HQ server only, as MESH_HQ_PRIVATE_KEY):
    $private

  PUBLIC (ships to handsets via app_config):
    $public

  Verified: this pair opens what it seals.
  Clear your scrollback.

''');
  });
}

Uint8List _bytes(BigInt value, int length) {
  final out = Uint8List(length);
  var v = value;
  for (var i = length - 1; i >= 0; i--) {
    out[i] = (v & BigInt.from(0xff)).toInt();
    v = v >> 8;
  }
  return out;
}

String _hex(Uint8List b) =>
    b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();
